public class Solution {
    public int search(int[] nums, int target) {
        int pivot = findPivot(nums);
        int left = 0;
        int right = nums.length - 1;

        while (left <= right) {
            int mid = (left + right) / 2;
            int realMid = (mid + pivot) % nums.length;
            int realLeft = (left + pivot) % nums.length;
            int realRight = (right + pivot) % nums.length;

            if (nums[realMid] == target) {
                return realMid;
            } else if (target > nums[realLeft] && target < nums[realMid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        return -1;
    }

    private int findPivot(int[] nums) {
        int pivot = 0;
        while (pivot < nums.length && nums[pivot] <= nums[(pivot + 1) % nums.length]) {
            pivot++;
        }
        return pivot;
    }

    public static void main(String[] args) {
        int[] nums = {4, 5, 6, 7, 0, 1, 2};
        System.out.println(new Solution().search(nums, 0));
        System.out.println(new Solution().search(nums, 3));
        System.out.println(new Solution().search(new int[]{1}, 0));
    }
}

