private void dfs(List<List<Integer>> graph, int[] time, boolean[] hasApple, int node, int currTime) {
    // If the given node has an apple, update the time required to collect it
    if (hasApple[node]) {
        time[node] = Math.max(time[node], currTime + 1);
    }

    // Traverse the graph from the given node
    for (int neighbor : graph.get(node)) {
        dfs(graph, time, hasApple, neighbor, time[node]);
    }
}

